{
  "name": "站点控制网络客户端",
  "name_en": "Site Control Network Client",
  "manufacturer": "",
  "description": "用于通过套接字连接实验站点服务并保持会话的非实体软件组件，可发送命令、接收响应，并按“knob”名称查询或设置远程配置项，适合实验控制系统中的远程参数访问与管理。",
  "description_en": "A non-physical software component that connects to a site service over a socket and keeps the session open. It can send commands, receive replies, and query or set remote configuration items by \"knob\" name for remote parameter access and management in lab control software.",
  "actions": [
    {
      "action_name": "auto-synchronized",
      "description": "对客户端操作进行同步，避免并发访问同一网络连接时发生冲突。",
      "description_en": "Synchronize client operations to avoid conflicts when multiple calls access the same network connection concurrently."
    },
    {
      "action_name": "auto-sr",
      "description": "发送一条命令消息并接收返回响应。",
      "description_en": "Send a command message and receive the reply."
    },
    {
      "action_name": "auto-build_knobs",
      "description": "根据提供的 knob 字符串动态构建可访问的参数项。",
      "description_en": "Dynamically build accessible knob properties from a provided knob string."
    },
    {
      "action_name": "auto-help",
      "description": "列出可用的 knob 参数项，并可按正则表达式过滤。",
      "description_en": "List available knob items, optionally filtered by a regular expression."
    },
    {
      "action_name": "auto-get_knob",
      "description": "读取指定名称的远程 knob 参数值。",
      "description_en": "Get the value of a named remote knob parameter."
    },
    {
      "action_name": "auto-set_knob",
      "description": "设置指定名称的远程 knob 参数值。",
      "description_en": "Set the value of a named remote knob parameter."
    }
  ],
  "tag_hints": [
    "socket client",
    "remote parameter access",
    "knob configuration",
    "lab control software",
    "command-response interface",
    "network session"
  ]
}

